fn first_word(s: &str) -> &str {
    &s[..s.find(' ').unwrap_or(s.len())]
}

fn main() {
    let my_string = String::from("hello world");
    println!("{}", first_word(&my_string[0..6])); // a slice of a String
    println!("{}", first_word(&my_string));       // a whole String
    println!("{}", first_word("hi there"));       // a literal
}

fn last_word(s: &str) -> &str {
    s // replace with a slice after the last space
}

fn main() {
    println!("{}", last_word("hello world"));
    println!("{}", last_word("Ferris"));
    let owned = String::from("Ferris the crab");
    println!("{}", last_word(&owned));
}

fn sum(values: &[i32]) -> i32 {
    let mut total = 0;
    for v in values {
        total += v;
    }
    total
}

fn double_all(values: &mut [i32]) {
    for v in values {
        *v *= 2;
    }
}

fn main() {
    let mut a = [1, 2, 3, 4, 5];
    println!("{}", sum(&a));        // the whole array
    println!("{}", sum(&a[1..3]));  // [2, 3]
    double_all(&mut a[3..]);        // only the last two
    println!("{a:?}");
}
